ALTER TABLE "supplier_pendings" DROP CONSTRAINT "supplier_pendings_type_check";--> statement-breakpoint
ALTER TABLE "supplier_pendings" DROP CONSTRAINT "supplier_pendings_sign";--> statement-breakpoint
